Translate("deDE", "western-plaguelands", {
	title = "Westliche Pestländer",
	aliases = { "die Westlichen Pestländer" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Westlichen Pestländer waren einst das nördliche Kernland von {link:lordaeron}Lordaeron{/link}: ein Land sanft gewellter Höfe, Obstgärten, Kornspeicher und wohlhabender Städte zwischen den Lichtungen von {link:tirisfal-glades}Tirisfal{/link} und dem Fluss, der nach Osten fließt. Heute sind sie ein graues und vergiftetes Land. Das Gras ist verdorrt, die Bäume stehen kahl, und die Felder, die ein Königreich ernährten, ernähren nur noch die {link:scourge}Geißel{/link}. Große Kessel hauchen über den alten Gehöften Seuche in die Luft. Die Toten wandeln auf den Straßen. Doch das Land ist nicht ganz verloren. Drei Mächte sind gekommen, um es den Toten streitig zu machen: die {link:alliance}Allianz{/link} aus dem Süden, die {link:forsaken}Verlassenen{/link} aus dem Westen und der {link:scarlet-crusade}Scharlachrote Kreuzzug{/link} von seiner Festung im Norden. Keine von ihnen traut den anderen.]=],
		},
		{
			title = "Ursprünge",
			text = [=[Keine Chronik verzeichnet das Jahr, in dem diese Lande zuerst besiedelt wurden. Sie gehörten zum Königreich {link:lordaeron}Lordaeron{/link}, solange dieses Königreich bestand, und sie zählten zu seinen reichsten. Die Stadt {link:ruins-of-andorhal}Andorhal{/link} sammelte die Ernten des Nordens in ihren Kornspeichern. Die Stadt {link:hearthglen}Hearthglen{/link} und die Burg Mardenholde bewachten die nördlichen Hügel, und in den Jahren nach dem {link:second-war}Zweiten Krieg{/link} wurden sie von {link:tirion-fordring}Tirion Fordring{/link} regiert, einem Lord und Paladin der Silbernen Hand. Im Süden hielt die Familie Barov die Inselburg {link:caer-darrow}Caer Darrow{/link} auf ihrem stillen See, und der Adel des Königreichs zog dorthin, um zu ruhen und sich am Wasser porträtieren zu lassen.]=],
		},
		{
			title = "Die Gegenwart",
			text = [=[Die {link:scourge}Geißel{/link} beherrscht die Westlichen Pestländer noch immer. Ein Lich namens {link:araj-the-summoner}Araj der Beschwörer{/link} hält die Ruinen von {link:ruins-of-andorhal}Andorhal{/link}. Vier Seuchenkessel, gehütet von Kesselfürsten, vergiften das Ackerland. Im Süden, unter {link:caer-darrow}Caer Darrow{/link}, bildet der Kult seine Totenbeschwörer in der Scholomance aus.

Gegen sie stehen kleine Streitkräfte an den Rändern des Landes. Im {link:chillwind-camp}Chillwind-Lager{/link} im Süden sammelt {link:commander-ashlam-valorfist}Kommandant Ashlam Valorfist{/link} die Soldaten und Streiter der {link:alliance}Allianz{/link} unter dem Banner des {link:kingdom-of-stormwind}Königreichs Stormwind{/link}. Am {link:the-bulwark}Bollwerk{/link} im Westen hält {link:high-executor-derrington}Hochexekutor Derrington{/link} das östliche Tor von {link:tirisfal-glades}Tirisfal{/link} für die Verlassenen und die {link:horde}Horde{/link}. Im Norden hält der Scharlachrote Kreuzzug {link:hearthglen}Hearthglen{/link} unter {link:taelan-fordring}Hochlord Taelan Fordring{/link}. Er bekämpft die Geißel, und er bekämpft auch alle anderen. Agenten der {link:argent-dawn}Argentumdämmerung{/link} dienen in den {link:camping}Lagern{/link} der Allianz wie der Horde und verlangen von keiner Seite etwas außer dem Krieg gegen die Toten.]=],
		},
		{
			title = "Bewohner",
			text = [=[• {b}Die {link:scourge}Geißel{/link}.{/b} Skelette, Ghule, Monstrositäten, Schemen und die ruhelosen Geister der Ertrunkenen und Erschlagenen. Sie halten {link:ruins-of-andorhal}Andorhal{/link}, {link:sorrow-hill}Sorrow Hill{/link} und die alten Höfe.
• {b}Der {link:cult-of-the-damned}Kult der Verdammten{/link}.{/b} Lebende Diener des Lichkönigs, die unter den Toten wirken, in Andorhal und in der Scholomance.
• {b}Die {link:alliance}Allianz{/link}.{/b} Soldaten aus {link:stormwind-city}Stormwind{/link}, Priester, Alchemisten und Agenten von {link:si-7}SI:7{/link} im {link:chillwind-camp}Chillwind-Lager{/link}.
• {b}Die Verlassenen.{/b} Die Besatzung des Bollwerks, die die Grenze für {link:sylvanas-windrunner}die Dunkle Fürstin{/link} hält.
• {b}Der Scharlachrote Kreuzzug.{/b} Ritter, Priester und Inquisitoren aus {link:hearthglen}Hearthglen{/link} und die Arbeiter des Sägewerks, das sie in Northridge an sich gerissen haben.
• {b}Die {link:argent-dawn}Argentumdämmerung{/link}.{/b} Offiziere und Verteidiger, in beiden {link:camping}Lagern{/link} stationiert.
• {b}Die ruhelosen Toten des alten Königreichs.{/b} Geister, die nie Teil der Geißel waren: die Geister von {link:caer-darrow}Caer Darrow{/link}, die Frau vom {link:felstone-field}Teufelssteinfeld{/link}, die Trauernden von Sorrow Hill.
• {b}Seuchenkranke Tiere.{/b} Wölfe, Bären, Fledermäuse und Geier, krank von derselben Seuche wie das Land.]=],
		},
		{
			title = "Geschichte",
			text = [=[• {b}Das Königreich.{/b} Über Generationen waren dies das Ackerland und die Flussstädte Lordaerons, reich und friedlich im Schutz der Stärke des Königreichs.
• {b}Der Zweite Krieg.{/b} Als die orcische {link:horde}Horde{/link} in den Norden einfiel, ritten die Ritter der Silbernen Hand gegen sie aus. {link:tirion-fordring}Tirion Fordring{/link} war unter ihnen. Nach dem Krieg herrschte er über die Lande um {link:hearthglen}Hearthglen{/link}, bis sie ihm genommen wurden, weil er einem {link:orcs}Orc{/link} das Leben geschenkt hatte.
• {b}Die Seuche.{/b} Vor dem {link:third-war}Dritten Krieg{/link} verseuchten Agenten des {link:cult-of-the-damned}Kults der Verdammten{/link} das Getreide in den Kornspeichern von {link:ruins-of-andorhal}Andorhal{/link}, und das Getreide ging hinaus in die Dörfer des Nordens. Wer davon aß, erkrankte, starb und erhob sich wieder als Diener des Lichkönigs. Prinz {link:arthas-menethil}Arthas Menethil{/link} kam nach Andorhal und erschlug den Meister des Kults, {link:kel-thuzad}Kel'Thuzad{/link}, doch die Seuche hatte sich bereits über jede Heilung hinaus ausgebreitet, und der Norden fiel Stadt um Stadt.
• {b}Der Fall Lordaerons.{/b} Nachdem Arthas seinen Vater ermordet hatte, wurde die Silberne Hand zerschlagen. {link:uther-the-lightbringer}Uther der Lichtbringer{/link} starb durch die Hand seines Schülers, und in diesen Landen wurde zu seinem Gedenken ein {link:the-sepulcher}Grabmal{/link} errichtet. Die Barovs von {link:caer-darrow}Caer Darrow{/link} übergaben ihre Burg dem Kult, und in ihren Grüften wurde die Scholomance gegründet.
• {b}Die Gegenwart.{/b} Die {link:scourge}Geißel{/link} hält das Herz des Landes. Die Lebenden klammern sich an seine Ränder, und der Kreuzzug hält den Norden.]=],
		},
		{
			title = "Kunde der Pestländer",
			text = [=[• Die Taschenuhren von {link:ruins-of-andorhal}Andorhal{/link} und die große Uhr an der Ruine seines Rathauses blieben alle zur selben Stunde stehen. Es war die Stunde, in der die Seuche die Stadt zuerst ergriff.
• Auf der Insel {link:caer-darrow}Caer Darrow{/link} sollen die Geister der Stadtbewohner ihren letzten glücklichen Tag immer und immer wieder erleben, als wäre ihnen nichts geschehen.
• Die Verlassenen und die {link:alliance}Allianz{/link} sagen beide, sie würden Andorhal einnehmen. Keine von beiden sagt, was sie mit der Stadt tun wird, wenn sie eingenommen ist.
• Unter den Toten von {link:sorrow-hill}Sorrow Hill{/link} liegen viele, die bei der Verteidigung von {link:darrowshire}Darrowshire{/link} im Osten fielen.]=],
		},
	},
})

Translate("deDE", "chillwind-camp", {
	title = "Chillwind-Lager",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Das Chillwind-Lager ist der Stützpunkt der {link:alliance}Allianz{/link} in den Westlichen Pestländern. Es steht am Südrand des Landes, über den Höhen von {link:alterac-mountains}Alterac{/link}, wo sich einige Zelte, eine Schmiede und ein Greifenhorst an den Hang klammern. Von hier aus plant {link:commander-ashlam-valorfist}Kommandant Ashlam Valorfist{/link} im Namen von {link:kingdom-of-stormwind}Stormwind{/link} den Krieg gegen {link:ruins-of-andorhal}Andorhal{/link}. Seine Priester erforschen die Seuche, sein Alchemist erforscht die Scholomance, und ein Agent von {link:si-7}SI:7{/link} wartet auf Nachricht aus dem Osten. Offiziere der {link:argent-dawn}Argentumdämmerung{/link} haben einen Posten unter ihnen. Auch {link:weldon-barov}Weldon Barov{/link}, der letzte lebende Lord seines Hauses, lebt hier unter dem Schutz des Lagers.]=],
		},
	},
})

Translate("deDE", "the-bulwark", {
	title = "Das Bollwerk",
	aliases = { "Bollwerk" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Das Bollwerk ist das befestigte Tor zwischen {link:tirisfal-glades}Tirisfal{/link} und den Pestländern. Seine Mauer und Türme wurden errichtet, um die {link:scourge}Geißel{/link} von den Landen der {link:forsaken}Verlassenen{/link} fernzuhalten, und die Verlassenen bemannen es jetzt. {link:high-executor-derrington}Hochexekutor Derrington{/link} befehligt hier. Vom Bollwerk aus schickt er seine Soldaten nach Osten gegen {link:ruins-of-andorhal}Andorhal{/link} und die Seuchenkessel und nach Norden gegen den {link:scarlet-crusade}Scharlachroten Kreuzzug{/link}. Apotheker und Schattenpriester arbeiten neben seinen Soldaten. Auch die {link:argent-dawn}Argentumdämmerung{/link} hat Offiziere am Tor. Ebenso {link:alexi-barov}Alexi Barov{/link}, ein verlassener Lord eines gefallenen Hauses, der hier auf Nachricht über das Vermögen seiner Familie wartet.]=],
		},
	},
})

Translate("deDE", "ruins-of-andorhal", {
	title = "Die Ruinen von Andorhal",
	aliases = { "Andorhal" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Andorhal war die große Kornspeicherstadt des nördlichen {link:lordaeron}Lordaeron{/link}. Die Ernten des Königreichs wurden in ihren Silos gelagert, und von dort schickte der {link:cult-of-the-damned}Kult der Verdammten{/link} das verseuchte Getreide aus, mit dem die Seuche begann. Hier stellte Prinz {link:arthas-menethil}Arthas Menethil{/link} {link:kel-thuzad}Kel'Thuzad{/link} und erschlug ihn. Nun ist die Stadt eine Ruine in der Hand der {link:scourge}Geißel{/link}. Vier Wachtürme bewachen ihre Zugänge, und im Herzen der Stadt hält der Lich {link:araj-the-summoner}Araj der Beschwörer{/link} Hof. Jede Uhr in Andorhal blieb zu der Stunde stehen, in der die Seuche sie ergriff. Im verfallenen Gasthaus an der Nordwestecke der Stadt hat sich eine seltsame Gnomin namens {link:chromie}Chromie{/link} eingerichtet.]=],
		},
	},
})

Translate("deDE", "hearthglen", {
	title = "Hearthglen",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Hearthglen steht in den Hügeln des hohen Nordens und blickt auf die Pestländer hinab. Es war die Stadt von {link:tirion-fordring}Tirion Fordring{/link}, der diese Lande von Burg Mardenholde aus regierte, bis er verbannt wurde. Im Krieg gegen die {link:scourge}Geißel{/link} hielt Prinz {link:arthas-menethil}Arthas Menethil{/link} Hearthglen gegen die Toten, bis {link:uther-the-lightbringer}Uther{/link} kam, um ihn zu entsetzen. Heute gehört die Stadt dem {link:scarlet-crusade}Scharlachroten Kreuzzug{/link}. Kreuzfahrer patrouillieren auf ihren Mauern, ihre Burg ist der Sitz von {link:taelan-fordring}Hochlord Taelan Fordring{/link}, und ihre Straße wird von Außenposten entlang des Passes von Hearthglen überwacht. Der Kreuzzug bewacht die Stadt eifersüchtig. Manche in {link:stormwind-city}Stormwind{/link} glauben, dass sie mehr als nur historische Bedeutung hat.]=],
		},
	},
})

Translate("deDE", "northridge-lumber-camp", {
	title = "Holzlager Northridge",
	aliases = { "Sägewerk Northridge" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Das Holzlager Northridge liegt südlich von {link:hearthglen}Hearthglen{/link}, westlich der Straße, die zur Stadt hinaufsteigt. Vor der Seuche war es ein Sägewerk, in dem die Familien des Nordens ihr Brot verdienten, indem sie das Holz der Hügel fällten und sägten. Der {link:scarlet-crusade}Scharlachrote Kreuzzug{/link} hat es genommen. Arbeiter und Holzfäller des Kreuzzugs schlagen nun Holz für die Mauern von Hearthglen, unter den Augen ihrer Vorarbeiter. Die Söhne der Familien, die einst hier arbeiteten, haben es nicht vergessen. Einer dient der {link:alliance}Allianz{/link} im {link:chillwind-camp}Chillwind-Lager{/link}, ein anderer den {link:forsaken}Verlassenen{/link} am {link:the-bulwark}Bollwerk{/link}, und beide wollen das Sägewerk lieber zerstört sehen, als es in den Händen des Kreuzzugs zu lassen.]=],
		},
	},
})

Translate("deDE", "felstone-field", {
	title = "Teufelssteinfeld",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Das Teufelssteinfeld war der Hof der Familie Felstone, nordwestlich von {link:ruins-of-andorhal}Andorhal{/link}. Sein Haus steht noch, ebenso seine Scheune, doch seine Felder dienen nun der {link:scourge}Geißel{/link}. Ein Seuchenkessel erhebt sich zwischen ihnen, gehütet vom Kesselfürsten Bilemaw und von den unerfahrensten der Toten. Im Obergeschoss des Bauernhauses verweilt der Geist von {link:janice-felstone}Janice Felstone{/link}. Sie weiß nicht, wie lange sie dort schon wartet. Sie spricht von einem Paket, das sie verschicken wollte, und von ihrem Mann John, als wäre die Seuche erst gestern gekommen.]=],
		},
	},
})

Translate("deDE", "dalson-s-tears", {
	title = "Dalsons Tränenfeld",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Dalsons Tränenfeld liegt fast genau nördlich von {link:ruins-of-andorhal}Andorhal{/link}. Es war der Hof der Familie Dalson, und den Namen, den es heute trägt, erhielt es nach der Seuche. Ein Kessel der {link:scourge}Geißel{/link} steht auf seinem Feld. Das Bauernhaus birgt ein auf der letzten Seite aufgeschlagenes Tagebuch, einen von verzweifelten Händen zerkratzten Schrank und einen Abort, dessen Tür von innen verbeult wurde. Ein Skelett wandert über den Hof. Die Geschichte, die diese Dinge erzählen, ist eine der traurigsten der Pestländer.]=],
		},
	},
})

Translate("deDE", "the-writhing-haunt", {
	title = "Das trostlose Feld",
	aliases = { "Trostloses Feld" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Das trostlose Feld ist ein verfallenes Gehöft östlich von {link:ruins-of-andorhal}Andorhal{/link}, nahe den zerbrochenen Mauern der Stadt. Die {link:scourge}Geißel{/link} hat hier einen ihrer Seuchenkessel errichtet, und der Boden ringsum wogt vor Toten. In einer Hütte auf dem Hof liegt ein {link:tauren}Tauren{/link}druide, der von weit her kam, um die Tiere dieses Landes zu heilen. Er fand kein Heilmittel, und er steckte sich selbst mit der Seuche an.]=],
		},
	},
})

Translate("deDE", "gahrron-s-withering", {
	title = "Gahrrons Trauerfeld",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Gahrrons Trauerfeld ist ein toter Hof im Nordosten der Westlichen Pestländer, nahe der Grenze zu den {link:eastern-plaguelands}Östlichen Pestländern{/link}. Hier steht der letzte der vier westlichen Kessel. Er wird von Schemen und Geistern bewacht, die zu den gefährlichsten Dienern der {link:scourge}Geißel{/link} in diesen Landen gehören, und vom Kesselfürsten Soulwrath. Keine Aufzeichnung erzählt, wer Gahrron war oder was aus den Leuten des Hofes wurde.]=],
		},
	},
})

Translate("deDE", "sorrow-hill", {
	title = "Sorrow Hill",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Sorrow Hill ist die große Begräbnisstätte der südlichen Pestländer, zwischen dem {link:chillwind-camp}Chillwind-Lager{/link} und {link:ruins-of-andorhal}Andorhal{/link}. Seine Hänge sind bedeckt mit Gräbern, Grüften und Denkmälern, darunter das {link:the-sepulcher}Grabmal{/link} von {link:uther-the-lightbringer}Uther dem Lichtbringer{/link}. Die Toten ruhen hier nicht. Skelette und Ghule steigen in solcher Zahl aus den Gräbern, dass die {link:scourge}Geißel{/link} den Hügel als lebende Mauer vor der östlichen Straße nach Andorhal nutzt. Zwischen den Grabsteinen wandelt der Geist von {link:marlene-redpath}Marlene Redpath{/link}, die noch immer nach Nachricht von der Nichte sucht, die sie in der Schlacht um {link:darrowshire}Darrowshire{/link} versteckte.]=],
		},
	},
})

Translate("deDE", "uther-s-tomb", {
	title = "Uthers Grabmal",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Uthers Grabmal steht auf {link:sorrow-hill}Sorrow Hill{/link}, ein Haus aus Stein, errichtet zum Gedenken an {link:uther-the-lightbringer}Uther den Lichtbringer{/link}, den ersten der Paladine der Silbernen Hand. Eine große Statue des Lichtbringers steht darin. Es ist einer der wenigen Orte in den Pestländern, die die Lebenden noch halten. {link:high-priest-thel-danis}Hohepriester Thel'danis{/link} bewacht das {link:the-sepulcher}Grabmal{/link} und reinigt die Steine der Toten vom Bösen. Auch eine alte Frau namens {link:myranda-the-hag}Myranda{/link} lebt dort. Einst war sie eine vertraute Ratgeberin von {link:tirion-fordring}Tirion Fordring{/link}.]=],
		},
	},
})

Translate("deDE", "caer-darrow", {
	title = "Caer Darrow",
	aliases = { "Darrowmeresee" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Caer Darrow ist eine Inselburg auf dem Darrowmeresee, im Südosten der Westlichen Pestländer. Über Generationen war sie der Sitz der Familie Barov und ein angenehmer Ort, an den die Adligen von {link:lordaeron}Lordaeron{/link} kamen, um am Wasser zu ruhen. Die Barovs übergaben sie dem {link:cult-of-the-damned}Kult der Verdammten{/link}. In den Grüften unter der Burg gründete der Kult die Scholomance, seine Schule der Totenbeschwörung. Die Stadt um die Burg ist leer von Lebenden. Ihre Geister sind geblieben: Bürger, Wachen, ein Bäcker und seine Kinder, ein Maler am Ufer. Die meisten von ihnen erleben ihren letzten glücklichen Tag immer und immer wieder. Einige wenige erinnern sich an alles, und sie wollen die Schule zerstört sehen.]=],
		},
	},
})

Translate("deDE", "taelan-fordring", {
	title = "Taelan Fordring",
	subtitle = "Hochlord des Scharlachroten Kreuzzugs",
	found = "In der Burg Mardenholde, in Hearthglen",
	hint = [=[Sucht den Hochlord in der Burg von Hearthglen auf. Der Kreuzzug heißt Fremde nicht willkommen.]=],
	allegiance = "Scharlachroter Kreuzzug",
	aliases = { "Taelan", "Hochlord Taelan Fordring" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Taelan Fordring ist der Hochlord des {link:scarlet-crusade}Scharlachroten Kreuzzugs{/link} in {link:hearthglen}Hearthglen{/link}. Er befehligt dessen Ritter von der Burg Mardenholde aus, dem Haus, in dem er geboren wurde. Er ist der Sohn von {link:tirion-fordring}Tirion Fordring{/link}, einst Herr dieser Lande. Taelan war ein Knabe, als sein Vater verbannt wurde, und man sagte ihm, sein Vater sei gestorben. Er hat es seitdem geglaubt.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Taelan ist der letzte der Fordrings, der die Lande seiner Familie hält, und er hält sie für einen Orden, der seinen Weg verloren hat. Er wurde im Licht erzogen und als Paladin der Silbernen Hand ausgebildet. Er kämpfte gegen die {link:scourge}Geißel{/link}, als das Königreich fiel. Von allen Anführern des Kreuzzugs ist er derjenige, in dem noch etwas vom alten Orden lebt.]=],
		},
		{
			title = "Frühe Jahre",
			text = [=[Taelan wuchs in der Burg Mardenholde auf, der Sohn von Lord {link:tirion-fordring}Tirion{/link} und seiner Frau Karandra. Als er ein kleiner Junge war, schenkte ihm sein Vater einen kleinen Kriegshammer, nach dem Vorbild seines eigenen gefertigt. Dann kam der Prozess. Tirion hatte einem {link:orcs}Orc{/link} das Leben geschenkt, und dafür wurden ihm seine Lande und Titel genommen, und er wurde aus dem Orden verstoßen. Karandra sagte ihrem Sohn, sein Vater sei tot. Taelan begrub den Spielzeughammer am falschen Grab und wuchs ohne ihn auf.]=],
		},
		{
			title = "Der Fall des Ordens",
			text = [=[Taelan folgte dem Weg seines Vaters zu den Rittern der Silbernen Hand. Als {link:uther-the-lightbringer}Uther{/link} fiel und der Orden zerschlagen wurde, kämpfte er an der Seite der letzten seiner Ritter weiter. Im Weiler {link:northdale}Northdale{/link} leistete er ein letztes Gefecht. Dort warf er in seiner Verzweiflung das Banner der Silbernen Hand nieder und sagte sich vom Orden los. Stattdessen schloss er sich dem Scharlachroten Kreuzzug an, und er stieg darin hoch auf.]=],
		},
		{
			title = "Taten",
			text = [=[• Er wurde als Paladin der Silbernen Hand ausgebildet.
• Er kämpfte beim Fall Lordaerons gegen die {link:scourge}Geißel{/link} und leistete in {link:northdale}Northdale{/link} ein letztes Gefecht.
• Er sagte sich von der Silbernen Hand los und schloss sich dem Scharlachroten Kreuzzug an.
• Er befehligt den Kreuzzug in {link:hearthglen}Hearthglen{/link} als dessen Hochlord.]=],
		},
	},
	chapters = {
		{
			title = "Tirions Geschenk",
			hint = [=[Tragt das Geschenk eines Vaters nach Hearthglen, verkleidet als einer seiner Verteidiger.]=],
			text = [=[Der Bote kam in einem Wappenrock des Kreuzzugs zur Burg Mardenholde, und Taelan hielt ihn für einen Teil der Verstärkung, die aus {link:tyr-s-hand}Tyrs Hand{/link} erwartet wurde. Dann öffnete er die Kiste. Darin lagen der Spielzeughammer aus dem Grab seines Vaters, das Banner, das er in {link:northdale}Northdale{/link} niedergeworfen hatte, und ein Gemälde von ihm als Kind, in den Armen seines Vaters und seiner Mutter am Ufer von {link:caer-darrow}Caer Darrow{/link}. Es waren nicht die Reliquien eines Toten. Taelan sank auf ein Knie. Er begriff, dass sein Vater lebte und dass man ihn den größten Teil seines Lebens belogen hatte.]=],
		},
		{
			title = "In Träumen",
			hint = "Helft dem Hochlord, Hearthglen zu verlassen.",
			text = [=[Taelan hatte lange von seinem Vater geträumt, der an seiner Seite gegen die Toten kämpfte. Nun beschloss er, zu ihm zu gehen. Er sagte sich von dem Kreuzzug los, dem er so lange gedient hatte, und kämpfte sich aus {link:hearthglen}Hearthglen{/link} hinaus. Jenseits der Mauern setzte der Kreuzzug ihm nach. Der Großinquisitor Isillien stellte ihn auf der Straße und erschlug ihn vor den Augen seines Vaters. {link:tirion-fordring}Tirion{/link} kniete über dem Leichnam seines Sohnes. Aus seiner Trauer erwuchs ein Schwur: Die Silberne Hand sei nicht tot, und er werde sie wieder erheben.]=],
		},
	},
	mentions = {
		{
			text = [=[Von vergessenen Erinnerungen, der Spielzeughammer am falschen Grab]=],
		},
		{
			text = [=[Von verlorener Ehre, das Banner von {link:northdale}Northdale{/link}]=],
		},
		{ text = "Von Liebe und Familie, das Gemälde" },
		{ text = "Findet {link:myranda-the-hag}Myranda{/link}" },
		{ text = "Scharlachrote Täuschung" },
		{ text = "In Träumen" },
	},
	bonds = {
		{ id = "tirion-fordring", name = "Tirion Fordring", note = "sein Vater" },
		{ id = "myranda-the-hag", name = "Myranda die Hexe", note = "die Ratgeberin seines Vaters" },
		{ id = "artist-renfray", name = "Künstler Renfray", note = "malte ihn als Kind" },
		{ id = "uther-the-lightbringer", name = "Uther der Lichtbringer", note = "führte den Orden, von dem er sich lossagte" },
	},
})

Translate("deDE", "commander-ashlam-valorfist", {
	title = "Kommandant Ashlam Valorfist",
	subtitle = "Kommandant des Chillwind-Lagers",
	found = "Chillwind-Lager, im Süden der Westlichen Pestländer",
	hint = [=[Sprecht mit dem Kommandanten, der die Allianz im Chillwind-Lager sammelt.]=],
	allegiance = "Königreich Stormwind · Allianz",
	aliases = { "Ashlam Valorfist", "Valorfist" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Kommandant Ashlam Valorfist führt die {link:alliance}Allianz{/link} in den Westlichen Pestländern an. Als {link:stormwind-city}Stormwind{/link} seinen Ruf zu den Waffen gegen die {link:scourge}Geißel{/link} des Nordens aussandte, wurden die Freiwilligen in sein Lager geschickt. Er ist ein kühner und lauter Mann, der Pläne und Lob liebt, und er will {link:ruins-of-andorhal}Andorhal{/link} den Toten wieder entreißen.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Valorfist ist das Schwert der {link:alliance}Allianz{/link} in den toten Landen von {link:lordaeron}Lordaeron{/link}. Sein Feldzug ist Stormwinds erster ernsthafter Versuch seit dem Fall des Königreichs, die {link:scourge}Geißel{/link} in ihrem eigenen Land zu treffen.]=],
		},
		{
			title = "Taten",
			text = [=[• Er errichtete das {link:chillwind-camp}Chillwind-Lager{/link} und rief im Namen Stormwinds Freiwillige dorthin.
• Er plante den Angriff auf {link:ruins-of-andorhal}Andorhal{/link} über die östliche Straße, durch {link:sorrow-hill}Sorrow Hill{/link}.
• Er ließ {link:morgan-s-vigil}die Wacht{/link}ürme von Andorhal für den Angriff markieren.
• Er setzte seine Priester daran, die Seuchenkessel gegen die {link:scourge}Geißel{/link} zu wenden.
• Er schickte Streiter aus, um den Schlüssel zur Scholomance zu suchen.]=],
		},
	},
	chapters = {
		{
			title = "Die Straße durch Sorrow Hill",
			hint = [=[Säubert den Hügel, der die östliche Straße nach Andorhal bewacht, von den Toten.]=],
			text = [=[Die westliche und die nördliche Straße nach {link:ruins-of-andorhal}Andorhal{/link} waren zu stark gehalten. Valorfist wählte die östliche Straße. Um sie zu erreichen, mussten seine Streitkräfte an {link:sorrow-hill}Sorrow Hill{/link} vorbei, wo sich die Toten zu Hunderten aus ihren Gräbern erhoben. Der erste Schlag seines Feldzugs wurde zwischen den Grabsteinen geführt.]=],
		},
		{
			title = "Die Wachtürme",
			hint = "Markiert die Türme von Andorhal für den Angriff.",
			text = [=[Die {link:scourge}Geißel{/link} nutzte vier Wachtürme, um ihre Streitkräfte durch {link:ruins-of-andorhal}Andorhal{/link} zu lenken. Valorfist ließ eine Signalfackel anfertigen, und mit ihr wurden die Türme einer nach dem anderen markiert. Seine Priester spürten die Leuchtfeuer hell brennen. Der Kommandant erklärte, die Zeit sei gekommen, den Kampf in die Stadt zu tragen.]=],
		},
		{
			title = "Die Kessel",
			hint = [=[Helft den Priestern des Kommandanten, die Seuchenkessel gegen die Geißel zu wenden.]=],
			text = [=[Die Kessel konnten nicht zerstört werden. Die Totenbeschwörung Kel'Thuzads war zu stark. Also plante Valorfists Stellvertreterin, {link:high-priestess-macdonnell}Hohepriesterin MacDonnell{/link}, zu verändern, was sie brauten. Alle vier westlichen Kessel wurden geöffnet, Proben ihrer Gifte genommen und ein Gegenmittel hergestellt. Als es vollbracht war, stellte sich der Kommandant vor sein Lager und brüllte seinen Dank an den Streiter hinaus, der es getan hatte, als einen Helden der {link:alliance}Allianz{/link}.]=],
		},
		{
			title = "Ach, Andorhal",
			hint = "Vernichtet den Lich, der über Andorhal herrscht.",
			text = [=[Schließlich schickte Valorfist seine Streiter ins Herz von {link:ruins-of-andorhal}Andorhal{/link}, gegen den Lich {link:araj-the-summoner}Araj{/link} den Beschwörer. Sie kehrten mit einem Splitter der Phylakterie des Lichs zurück. Der Kommandant nannte es einen Sieg für die Ewigkeit.]=],
		},
	},
	mentions = {
		{ text = "Ein Ruf zu den Waffen: Die Pestländer!" },
		{ text = "Macht den Weg frei" },
		{ text = "Entlang der Wachtürme" },
		{ text = "Die Seuchenkessel der {link:scourge}Geißel{/link}" },
		{ text = "Mission erfüllt!" },
		{ text = "Scholomance" },
		{ text = "Ach, {link:ruins-of-andorhal}Andorhal{/link}" },
		{
			text = [=[{link:chillwind-point}Chillwindspitze{/link}, Nachricht von {link:grayson-shadowbreaker}Lord Grayson Shadowbreaker{/link}]=],
		},
		{ text = "Träge Geißelsteine" },
		{
			text = [=[Das Schmieden des Machtsteins, mit Federn von den Trollen des versunkenen Tempels]=],
		},
	},
	bonds = {
		{ id = "high-priestess-macdonnell", name = "Hohepriesterin MacDonnell", note = "seine Stellvertreterin" },
		{ id = "alchemist-arbington", name = "Alchemist Arbington", note = "sein Gelehrter der Scholomance" },
		{ id = "high-priest-thel-danis", name = "Hohepriester Thel'danis", note = "reinigt die Steine, die er braucht" },
		{ id = "grayson-shadowbreaker", name = "Grayson Shadowbreaker", note = "schickt ihm Paladine" },
		{ id = "high-executor-derrington", name = "Hochexekutor Derrington", note = "der Befehlshaber der Horde mit demselben Ziel" },
		{ id = "araj-the-summoner", name = "Araj der Beschwörer", note = "Feind" },
	},
})

Translate("deDE", "high-executor-derrington", {
	title = "Hochexekutor Derrington",
	subtitle = "Befehlshaber des Bollwerks",
	found = "Das Bollwerk, am Ostrand von Tirisfal",
	hint = "Sprecht mit dem Hochexekutor, der das Bollwerk hält.",
	allegiance = "Verlassene · Horde",
	aliases = { "Derrington" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Hochexekutor Derrington befehligt die {link:forsaken}Verlassenen{/link} am {link:the-bulwark}Bollwerk{/link}, dem befestigten Tor zwischen {link:tirisfal-glades}Tirisfal{/link} und den Pestländern. Als die {link:horde}Horde{/link} ihre Streiter gegen die {link:scourge}Geißel{/link} des Nordens rief, wurden sie zu ihm geschickt. Er ist ein listiger Befehlshaber. Er kämpft nicht gegen zwei Feinde zugleich, wenn er sie gegeneinander aufbringen kann.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Derrington hält die Ostgrenze des Reiches der Dunklen Fürstin. {link:the-bulwark}Das Bollwerk{/link} ist die Mauer zwischen {link:undercity}Undercity{/link} und den toten Landen, und von dort aus führt er den Krieg der Verlassenen um {link:ruins-of-andorhal}Andorhal{/link}.]=],
		},
		{
			title = "Taten",
			text = [=[• Er hält das {link:the-bulwark}Bollwerk{/link} für die Verlassenen und die {link:horde}Horde{/link}.
• Er wandte den Scharlachroten Kreuzzug mit einem verbrannten Zelt und einem falschen Banner gegen die {link:scourge}Geißel{/link}.
• Er ließ {link:morgan-s-vigil}die Wacht{/link}ürme von {link:ruins-of-andorhal}Andorhal{/link} für den Angriff markieren.
• Er setzte seine Schattenpriester daran, die Seuchenkessel gegen die Geißel zu wenden.
• Er schickte Streiter aus, um den Schlüssel zur Scholomance zu suchen.]=],
		},
	},
	chapters = {
		{
			title = "Scharlachrote Ablenkung",
			hint = "Hetzt den Kreuzzug und die Geißel gegeneinander.",
			text = [=[Der Scharlachrote Kreuzzug war von {link:hearthglen}Hearthglen{/link} aus nach Süden vorgedrungen und hatte zwischen dem {link:felstone-field}Teufelssteinfeld{/link} und {link:dalson-s-tears}Dalsons Tränenfeld{/link} ein Lager aufgeschlagen. Derrington wollte nicht gegen den Kreuzzug und die {link:scourge}Geißel{/link} zugleich kämpfen. Er ließ das Befehlszelt des Kreuzzugs mit Flammen aus der Flasche niederbrennen und neben der Asche ein Banner der Geißel aufpflanzen. Dann schickte er einen Späher, um zuzusehen, wie die Kreuzfahrer den Köder schluckten.]=],
		},
		{
			title = "Die Wachtürme",
			hint = "Markiert die Türme von Andorhal für den Angriff.",
			text = [=[Mit dem abgelenkten Kreuzzug wandte sich Derrington {link:ruins-of-andorhal}Andorhal{/link} zu. Die Toten nutzten vier Wachtürme, um ihre Bewegungen zu lenken. Seine Hexenmeister fertigten eine Signalfackel an, und die Türme wurden für den Angriff markiert. Der Hochexekutor war zufrieden. Nun, sagte er, werde es zu einem offenen Kampf um die Stadt kommen.]=],
		},
		{
			title = "Die Kessel",
			hint = [=[Helft den Schattenpriestern, die Seuchenkessel gegen die Geißel zu wenden.]=],
			text = [=[Die vier Kessel des Westens konnten nicht stillgelegt, aber verändert werden. {link:shadow-priestess-vandis}Schattenpriesterin Vandis{/link} kümmerte sich um die Arbeit. Als alle vier geöffnet und ihre Gifte gegen ihre Schöpfer gewendet waren, rief Derrington vor dem ganzen {link:the-bulwark}Bollwerk{/link} den Namen des Streiters aus, der es getan hatte.]=],
		},
		{
			title = "Ach, Andorhal",
			hint = "Vernichtet den Lich, der über Andorhal herrscht.",
			text = [=[Zuletzt kam der Schlag gegen den Lich {link:araj-the-summoner}Araj{/link} den Beschwörer. Seine Streiter brachten einen Splitter der Phylakterie des Lichs zurück, und Derrington verkündete ihn als Sieg für die {link:horde}Horde{/link}.]=],
		},
	},
	mentions = {
		{ text = "Ein Ruf zu den Waffen: Die Pestländer!" },
		{ text = "Scharlachrote Ablenkung" },
		{ text = "Entlang der Wachtürme" },
		{ text = "Die Seuchenkessel der {link:scourge}Geißel{/link}" },
		{ text = "Mission erfüllt!" },
		{ text = "Scholomance" },
		{ text = "Der Schlüssel zur Scholomance" },
		{ text = "Ach, {link:ruins-of-andorhal}Andorhal{/link}" },
	},
	bonds = {
		{ id = "shadow-priestess-vandis", name = "Schattenpriesterin Vandis", note = "seine Stellvertreterin" },
		{ id = "apothecary-dithers", name = "Apotheker Dithers", note = "sein Gelehrter der Scholomance" },
		{ id = "alexi-barov", name = "Alexi Barov", note = "ein Lord unter seinem Schutz" },
		{ id = "sylvanas-windrunner", name = "Sylvanas Windrunner", note = "seine Königin" },
		{ id = "commander-ashlam-valorfist", name = "Kommandant Ashlam Valorfist", note = "der Befehlshaber der Allianz mit demselben Ziel" },
		{ id = "araj-the-summoner", name = "Araj der Beschwörer", note = "Feind" },
	},
})

Translate("deDE", "chromie", {
	title = "Chromie",
	subtitle = "Die seltsame Historikerin",
	found = "Das verfallene Gasthaus an der Nordwestecke von Andorhal",
	hint = [=[Sucht die Gnomin, die im verfallenen Gasthaus von Andorhal lebt.]=],
	allegiance = "Unbekannt",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Chromie ist eine kleine Gnomin, die sich im verfallenen Gasthaus von {link:ruins-of-andorhal}Andorhal{/link} eingerichtet hat, in einer Stadt, die von den Toten gehalten wird. Das Zimmer, das sie bewohnt, ist seltsam unversehrt, als hätte die Ruine ringsum es nicht berührt. Sie spricht von der Zeit, wie andere Leute vom Wetter sprechen. Sie fragt Reisende, ob sie aus der Zukunft kommen, und sie scheint nicht zu scherzen.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Chromie behauptet, etwas habe in {link:ruins-of-andorhal}Andorhal{/link} den Fluss der Zeit manipuliert, und sie sei gekommen, um ihn zu richten. Was auch immer sie ist, sie weiß weit mehr, als eine Gnomin wissen sollte, über die Vergangenheit der Stadt und über das Schicksal jener, die im Krieg starben.]=],
		},
		{
			title = "Taten",
			text = [=[• Sie bewohnt ein Zimmer im verfallenen Gasthaus von {link:ruins-of-andorhal}Andorhal{/link}.
• Sie jagt die Kreaturen, die sich vom gebrochenen Fluss der Zeit in der Stadt nähren.
• Sie sammelt die stehen gebliebenen Taschenuhren von Andorhal.
• Sie sucht das Schicksal von {link:joseph-redpath}Joseph Redpath{/link} aus {link:darrowshire}Darrowshire{/link} zu erfahren und es zu ändern.]=],
		},
	},
	chapters = {
		{
			title = "Eine Frage der Zeit",
			hint = [=[Helft der Gnomin im Gasthaus mit den Parasiten in den Silos von Andorhal.]=],
			text = [=[Chromie sagte, die Zeitlinie von {link:ruins-of-andorhal}Andorhal{/link} sei manipuliert worden, höchstwahrscheinlich von der {link:scourge}Geißel{/link}. Kreaturen, die sich von gebrochener Zeit nähren, hatten sich in den Silos gesammelt, und sie störten ihre Arbeit. Als sie ausgerottet waren, sprach sie offener. Sie ist gar keine Gnomin. Sie dient dem bronzenen Drachenschwarm, den Hütern der Zeit, und ihre wahre Gestalt ist verborgen.]=],
		},
		{
			title = "Die Zeit zählen",
			hint = [=[Bringt Chromie die stehen gebliebenen Taschenuhren von Andorhal.]=],
			text = [=[Um den Schaden an {link:ruins-of-andorhal}Andorhal{/link} zu beheben, arbeitet Chromie von einem anderen Faden der Zeit aus, um ihn nicht weiter zu stören. Sie braucht Kleinode aus dem Augenblick, in dem die Seuche zuschlug. Die Taschenuhren der Stadt erfüllen diesen Zweck, denn alle blieben um drei Uhr stehen, zu der Stunde, in der sich die Seuche zuerst ausbreitete. Was Chromie im Gegenzug gibt, sind Gaben, deren Nutzen, wie sie sagt, sich mit der Zeit zeigen wird.]=],
		},
		{
			title = "Die Annalen von Darrowshire",
			hint = "Findet die Chronik von Darrowshire im Rathaus von Andorhal.",
			text = [=[Der Geist von {link:marlene-redpath}Marlene Redpath{/link} schickte Chromie einen Ring, den Ehering von {link:joseph-redpath}Joseph Redpath{/link}. Chromie wusste sofort, dass er einem großen Mann mit tragischer Vergangenheit gehört hatte. Die Annalen von {link:darrowshire}Darrowshire{/link}, verwahrt im Rathaus von {link:ruins-of-andorhal}Andorhal{/link}, erzählten den Rest: In der Schlacht um Darrowshire wurde Joseph verderbt und gegen dessen Verteidiger gewandt. Chromie beschloss, dieses Schicksal zu ändern, wenn sie konnte.]=],
		},
	},
	mentions = {
		{ text = "Eine Frage der Zeit" },
		{ text = "Die Zeit zählen" },
		{ text = "Eine seltsame Historikerin" },
		{ text = "Annalen von {link:darrowshire}Darrowshire{/link}" },
		{ text = "{link:carlin-redpath}Bruder Carlin{/link}" },
		{ text = "Zurück zu Chromie" },
		{ text = "Die Schlacht um {link:darrowshire}Darrowshire{/link}" },
	},
	bonds = {
		{ id = "marlene-redpath", name = "Marlene Redpath", note = "schickte ihr Josephs Ring" },
		{ id = "jeziba", name = "Jeziba", note = "teilt ihre Ecke der verfallenen Stadt" },
	},
})

Translate("deDE", "araj-the-summoner", {
	title = "Araj der Beschwörer",
	subtitle = "Lich von Andorhal",
	found = "Das Herz der Ruinen von Andorhal",
	hint = "Stellt Euch dem Lich, der das Herz von Andorhal hält.",
	allegiance = "Geißel",
	aliases = { "Araj" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Araj der Beschwörer ist ein Lich der {link:scourge}Geißel{/link}. Er herrscht vom Herzen der Stadt aus über die Ruinen von {link:ruins-of-andorhal}Andorhal{/link}, bewacht von den Toten, die ihre Mitte umringen, und von einem eigenen Gefolge. Sowohl die {link:alliance}Allianz{/link} als auch die Verlassenen haben ihn als den Herrn von Andorhal ausgemacht, den sie vernichten müssen.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Araj führte einst die Scholomance, die Schule der Totenbeschwörung des Kults unter {link:caer-darrow}Caer Darrow{/link}, bevor er {link:ruins-of-andorhal}Andorhal{/link} für sich beanspruchte. Sein Siegel, ein Skarabäus, ist eines der wenigen Dinge, die die versiegelte Tür der Schule öffnen können.]=],
		},
		{
			title = "Taten",
			text = [=[• Er führte die Scholomance, bevor er {link:ruins-of-andorhal}Andorhal{/link} nahm.
• Er herrscht für die {link:scourge}Geißel{/link} über die Ruinen von Andorhal.
• Sein Skarabäus ist der Kopf des Schlüssels zur Scholomance.]=],
		},
	},
	chapters = {
		{
			title = "Der Skarabäus",
			hint = [=[Erfahrt, was die Alchemisten der Pestländer von dem Lich brauchen.]=],
			text = [=[Die Tür der Scholomance kann nur mit einem Schlüssel aus Knochen geöffnet werden, gebunden mit dem Siegel eines Wesens, das sie von Rechts wegen öffnen konnte. Araj war einst Meister der Schule. Sein Skarabäus, seiner gefallenen Phylakterie entnommen, wurde zum Kopf des Schlüssels.]=],
		},
		{
			title = "Der Fall von Araj",
			hint = "Vernichtet den Lich von Andorhal.",
			text = [=[Streiter der {link:alliance}Allianz{/link} wie der {link:horde}Horde{/link} brachen ins Herz von {link:ruins-of-andorhal}Andorhal{/link} ein und schlugen sich durch die Wachen des Lichs. Sie zerstörten seine Phylakterie, und ein Splitter davon ging als Beweis zurück ins {link:chillwind-camp}Chillwind-Lager{/link} und ans {link:the-bulwark}Bollwerk{/link}.]=],
		},
	},
	mentions = {
		{ text = "Ach, {link:ruins-of-andorhal}Andorhal{/link}" },
		{ text = "Arajs Skarabäus" },
	},
	bonds = {
		{ id = "commander-ashlam-valorfist", name = "Kommandant Ashlam Valorfist", note = "Feind" },
		{ id = "high-executor-derrington", name = "Hochexekutor Derrington", note = "Feind" },
		{ id = "kel-thuzad", name = "Kel'Thuzad", note = "der Meister seines Meisters" },
	},
})

Translate("deDE", "myranda-the-hag", {
	title = "Myranda die Hexe",
	subtitle = "Die Illusionistin von Uthers Grabmal",
	found = "Bei Uthers Grabmal, auf Sorrow Hill",
	hint = [=[Sucht die alte Frau, die beim Grabmal des Lichtbringers lebt.]=],
	allegiance = "Keine (einst das Haus von Tirion Fordring)",
	aliases = { "Myranda" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Myranda ist eine alte Frau, die bei {link:uther-s-tomb}Uthers Grabmal{/link} lebt und sich eine Illusionistin nennt. Einst war sie die vertrauteste Ratgeberin von {link:tirion-fordring}Tirion Fordring{/link}, als er Herr von Mardenholde war. Als der Orden ihn verurteilte, sprach sie sich offen gegen das Urteil aus, und dafür wurde sie verbannt. Sie hat lange auf eine Gelegenheit gewartet, das den Fordrings angetane Unrecht wiedergutzumachen.]=],
		},
		{
			title = "Taten",
			text = [=[• Sie beriet {link:tirion-fordring}Tirion Fordring{/link} als Herrn von Mardenholde.
• Sie wurde verbannt, weil sie sich dem Urteil gegen ihn widersetzte.
• Sie wirkt Illusionen, die es Fremden erlauben, unter Feinden zu wandeln.]=],
		},
	},
	chapters = {
		{
			title = "Scharlachrote Täuschung",
			hint = "Bringt der alten Frau ein Geschenk von Tirion.",
			text = [=[Als Tirions Bote zu ihr kam, sagte Myranda nur, sie habe gewusst, dass dieser Tag kommen würde. Sie verlieh dem Boten die Gestalt eines scharlachroten Kreuzfahrers, damit Tirions Geschenk nach {link:hearthglen}Hearthglen{/link} getragen werden konnte. Die Illusion kostet sie viel, und sie verblasst, wenn ihr Träger sich zu weit von diesen Landen entfernt.]=],
