Translate("deDE", "weldon-barov", {
	title = "Weldon Barov",
	subtitle = "Erbe des Hauses Barov",
	found = "Chillwind-Lager",
	hint = [=[Sucht den stolzen Edelmann, der im Chillwind-Lager Zuflucht gefunden hat.]=],
	allegiance = "Haus Barov · Allianz",
	aliases = { "Weldon" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Weldon Barov ist einer der letzten beiden Erben des Hauses Barov, der Familie, die {link:caer-darrow}Caer Darrow{/link} hielt. Als die Seuche kam, floh er und überlebte. Sein Bruder Alexi floh nicht und ist nun einer der {link:forsaken}Verlassenen{/link}. Weldon lebt im {link:chillwind-camp}Chillwind-Lager{/link} unter dem Schutz der {link:alliance}Allianz{/link}. Er ist hochmütig gegenüber allen, die ihm dienen, und denkt an kaum etwas anderes als an sein Erbe.]=],
		},
		{
			title = "Taten",
			text = [=[• Er floh vor dem Fall seines Hauses und behielt sein Leben.
• Er verschonte einst seinen untoten Bruder und bereut es.
• Er sucht die Urkunden der Ländereien der Barovs, die in der Scholomance verloren gingen.]=],
		},
	},
	chapters = {
		{
			title = "Der letzte Barov",
			hint = [=[Hört, was der Edelmann aus Chillwind wegen seines Bruders unternommen haben will.]=],
			text = [=[Mit den Urkunden für {link:caer-darrow}Caer Darrow{/link}, {link:brill}Brill{/link}, {link:tarren-mill}Tarrens Mühle{/link} und {link:southshore}Southshore{/link} in seinen Händen wollte Weldon noch eines. Er wollte den Kopf seines Bruders, vom {link:the-bulwark}Bollwerk{/link} zu ihm gebracht. Er würde die Tat nicht selbst begehen. Solche Dinge, sagte er, seien unter der Würde eines Mannes seiner Herkunft.]=],
		},
	},
	mentions = {
		{ text = "Das Vermögen der Familie Barov" },
		{ text = "Der letzte Barov" },
	},
	bonds = {
		{ id = "alexi-barov", name = "Alexi Barov", note = "sein Bruder und Rivale" },
	},
})

