Translate("deDE", "high-priestess-macdonnell", {
	title = "Hohepriesterin MacDonnell",
	subtitle = "Stellvertreterin im Chillwind-Lager",
	found = "Chillwind-Lager",
	hint = [=[Sprecht mit der Priesterin, die im Chillwind-Lager die Seuche erforscht.]=],
	allegiance = "Allianz · Kirche des Heiligen Lichts",
	aliases = { "MacDonnell" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Hohepriesterin MacDonnell ist die Stellvertreterin im Befehl über das {link:chillwind-camp}Chillwind-Lager{/link}. Sie leitet die Bemühungen der {link:alliance}Allianz{/link} gegen die Seuchenkessel. Sie weiß, dass die Kessel nicht zerstört werden können, also will sie verändern, was sie brauen, und es in ein Gift für die Toten verwandeln.]=],
		},
		{
			title = "Taten",
			text = [=[• Sie plante die Sabotage der vier westlichen Kessel.
• Sie schickte Streiter zum {link:felstone-field}Teufelssteinfeld{/link}, nach {link:dalson-s-tears}Dalsons Tränenfeld{/link}, zum Trostlosen Feld und nach {link:gahrron-s-withering}Gahrrons Trauerfeld{/link}, um Proben ihrer Gifte zu holen.]=],
		},
	},
	chapters = {
		{
			title = "Die vier Kessel",
			hint = "Bringt der Priesterin Proben aus den vier Kesseln.",
			text = [=[Jeder Kessel hatte sein eigenes Gebräu, und jeder wurde von einem Kesselfürsten bewacht, der den Schlüssel trug. Einer nach dem anderen wurden die Kessel geöffnet. Der letzte, in {link:gahrron-s-withering}Gahrrons Trauerfeld{/link}, wurde von Schemen und Geistern gehalten. Mit vier Proben in der Hand konnte MacDonnell ihr Gegenmittel herstellen.]=],
		},
	},
	mentions = {
		{ text = "Die Seuchenkessel der {link:scourge}Geißel{/link}" },
		{ text = "Ziel: {link:felstone-field}Teufelssteinfeld{/link}" },
		{ text = "Ziel: {link:dalson-s-tears}Dalsons Tränenfeld{/link}" },
		{ text = "Ziel: {link:the-writhing-haunt}Das trostlose Feld{/link}" },
		{ text = "Ziel: {link:gahrron-s-withering}Gahrrons Trauerfeld{/link}" },
	},
	bonds = {
		{ id = "commander-ashlam-valorfist", name = "Kommandant Ashlam Valorfist", note = "ihr Kommandant" },
		{ id = "shadow-priestess-vandis", name = "Schattenpriesterin Vandis", note = "tut dieselbe Arbeit für die Horde" },
	},
})

Translate("deDE", "alchemist-arbington", {
	title = "Alchemist Arbington",
	subtitle = "Gelehrter der Scholomance",
	found = "Chillwind-Lager",
	hint = "Sprecht mit dem Alchemisten des Chillwind-Lagers.",
	allegiance = "Allianz",
	aliases = { "Arbington" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Alchemist Arbington hat einen großen Teil seiner jüngsten Studien der Scholomance gewidmet. Er glaubt zu wissen, wie man einen Schlüssel zu ihrer versiegelten Tür herstellt. Er ist ein Gelehrter, kein Kämpfer, und er fragt sich offen, wie irgendjemand den Mut findet, dorthin zu gehen, wohin er sie schickt.]=],
		},
		{
			title = "Taten",
			text = [=[• Er erforscht die Scholomance für die {link:alliance}Allianz{/link}.
• Er ersann die Schmiedung des Skelettschlüssels.]=],
		},
	},
	chapters = {
		{
			title = "Der Skelettschlüssel",
			hint = [=[Helft dem Alchemisten, einen Schlüssel zur Scholomance zu schmieden.]=],
			text = [=[Der Schlüssel musste aus Knochen gefertigt sein, von vielen Skeletten der Toten genommen und gehärtet, um die Schmiede zu überstehen. Seine Gussform kam von einem Goblinschmied in {link:tanaris}Tanaris{/link}, der an jeden verkaufte, der zahlte. Sein Kopf war der Skarabäus des Lichs {link:araj-the-summoner}Araj{/link}, der einst Meister der Schule gewesen war. Arbington verschmolz sie miteinander und übergab den fertigen Schlüssel.]=],
		},
	},
	mentions = {
		{ text = "Scholomance" },
		{ text = "Skelettfragmente" },
		{ text = "Gussform reimt sich auf ..." },
		{ text = "Im Feuerfedergrat geschmiedet" },
		{ text = "Arajs Skarabäus" },
		{ text = "Der Schlüssel zur Scholomance" },
	},
	bonds = {
		{ id = "commander-ashlam-valorfist", name = "Kommandant Ashlam Valorfist", note = "sein Kommandant" },
		{ id = "apothecary-dithers", name = "Apotheker Dithers", note = "arbeitet für die Horde an demselben Schlüssel" },
		{ id = "araj-the-summoner", name = "Araj der Beschwörer", note = "der Lich, dessen Skarabäus er brauchte" },
	},
})

Translate("deDE", "nathaniel-dumah", {
	title = "Nathaniel Dumah",
	subtitle = "Sohn von Northridge",
	found = "Chillwind-Lager",
	hint = [=[Sprecht mit dem Mann im Chillwind-Lager, der den Kreuzzug hasst.]=],
	allegiance = "Allianz",
	aliases = { "Dumah" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Nathaniel Dumah lebt im {link:chillwind-camp}Chillwind-Lager{/link}. Der Geist seines Vaters findet keine Ruhe, solange der {link:scarlet-crusade}Scharlachrote Kreuzzug{/link} das Sägewerk in Northridge hält. Nathaniel hat versucht, die Kreuzfahrer mit Gewalt zu vertreiben, und ist gescheitert. Nun will er das Sägewerk für sie unbrauchbar machen.]=],
		},
		{
			title = "Taten",
			text = [=[• Er kämpfte erfolglos gegen den Scharlachroten Kreuzzug in Northridge.
• Er ersann einen Plan, das Sägewerk mit Termiten aus den Östlichen Pestländern zu ruinieren.]=],
		},
	},
	chapters = {
		{
			title = "Eine Plage über euch",
			hint = [=[Helft Nathaniel, das Sägewerk zu ruinieren, das der Kreuzzug genommen hat.]=],
			text = [=[Die Termiten des Pestwalds hatten sowohl die Seuche als auch die {link:scourge}Geißel{/link} überdauert. Ein Fass davon wurde in das Sägewerk von Northridge getragen und geöffnet. Nathaniel lachte, als er hörte, dass es vollbracht war. Der Geist seines Vaters, sagte er, könne nun ruhen, und er ebenso.]=],
		},
	},
	mentions = {
		{ text = "Eine Plage über euch" },
	},
	bonds = {
		{ id = "mickey-levine", name = "Mickey Levine", note = "teilt seine Sache am Bollwerk" },
	},
})

