Translate("deDE", "janice-felstone", {
	title = "Janice Felstone",
	subtitle = "Der Geist vom Teufelssteinfeld",
	found = "Das Obergeschoss des Bauernhauses auf dem Teufelssteinfeld",
	hint = [=[Steigt ins Obergeschoss des Bauernhauses der Felstones hinauf.]=],
	allegiance = "Keine",
	aliases = { "Janice" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der Geist von Janice Felstone spukt in ihrem Bauernhaus auf dem {link:felstone-field}Teufelssteinfeld{/link}. Sie nimmt die Welt nur halb wahr. Sie spricht von einem Paket, das sie vor der Seuche verschicken wollte und das sie bei ihrem Pferd in der Scheune ließ. Sie ruft nach ihrem Mann John und fürchtet die Ghule draußen.]=],
		},
		{
			title = "Taten",
			text = [=[• Sie schnürte ein Paket für ihre Schwester Emma in {link:stormwind-city}Stormwind{/link} oder für ihren Bruder Jeremiah in der {link:capital-city}Hauptstadt{/link} von {link:lordaeron}Lordaeron{/link}.
• Sie teilte einen Glücksbringer mit ihrem Mann John, jeder eine Hälfte.]=],
		},
	},
	chapters = {
		{
			title = "Aus zwei Hälften wird eins",
			hint = "Macht den Glücksbringer wieder ganz.",
			text = [=[Das Paket erreichte seinen Empfänger Jahre zu spät. Janices Schwester Emma war zu einer Herumtreiberin in den Straßen von {link:stormwind-city}Stormwind{/link} geworden. Ihr Bruder Jeremiah war einer der {link:forsaken}Verlassenen{/link} geworden und hatte seinen Namen geändert. Wer es auch erhielt, schickte Janices Hälfte ihres Glücksbringers zurück. Die andere Hälfte war noch auf dem Hof. Als der Glücksbringer wieder ganz war und in ihre Hände gelegt wurde, klärten sich die Augen des Geistes. Sie war frei.]=],
		},
	},
	mentions = {
		{ text = "Besser spät als nie" },
		{ text = "Glücksbringer" },
		{ text = "Aus zwei Hälften wird eins" },
	},
})

Translate("deDE", "farmer-dalson", {
	title = "Bauer Dalson",
	subtitle = "Das Ding im Abort",
	found = "Eingeschlossen im Abort auf Dalsons Tränenfeld",
	hint = [=[Findet, was die Frau des Bauern auf Dalsons Tränenfeld eingeschlossen hat.]=],
	allegiance = "Geißel",
	aliases = { "Harold Dalson" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Harold Dalson bewirtschaftete das Land, das heute {link:dalson-s-tears}Dalsons Tränenfeld{/link} heißt. Als die Seuche kam, verwandelte er sich. Seine Frau schleifte ihn an den einzigen Ort auf dem Hof, der sich fest verschließen ließ, den Abort, und versteckte den Schlüssel bei sich. Sie hoffte zu entkommen. Dazu brauchte sie Geld, doch die Wertsachen der Familie waren in einem Schrank eingeschlossen, und der Schlüssel zum Schrank war bei Harold.]=],
		},
		{
			title = "Taten",
			text = [=[• Er wurde von der Seuche verwandelt.
• Er wurde von seiner Frau eingeschlossen, mit dem Schlüssel zum Schrank seiner Familie noch bei sich.]=],
		},
	},
	chapters = {
		{
			title = "Weggeschlossen",
			hint = "Öffnet, was Frau Dalson verschlossen hat.",
			text = [=[Frau Dalson verließ den Hof nie. Ihr Skelett wandert noch immer über den Hof, und der Schlüssel zum Abort war noch bei ihm. Als die Tür geöffnet wurde, brach ein Ghul schreiend heraus. Harold war nicht mehr zu retten.]=],
		},
	},
	mentions = {
		{ text = "Frau Dalsons Tagebuch" },
		{ text = "Weggeschlossen" },
	},
})

Translate("deDE", "marlene-redpath", {
	title = "Marlene Redpath",
	subtitle = "Geist von Darrowshire",
	found = "Zwischen den Gräbern von Sorrow Hill",
	hint = [=[Sucht den trauernden Geist zwischen den Gräbern von Sorrow Hill.]=],
	allegiance = "Keine",
	aliases = { "Marlene" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Marlene Redpath ist ein wandernder Geist auf {link:sorrow-hill}Sorrow Hill{/link}. Sie starb in der Schlacht um {link:darrowshire}Darrowshire{/link}, in der so viele starben und manche zu etwas Schlimmerem als Toten wurden. Als die Schlacht begann, versteckte sie ihre Nichte {link:pamela-redpath}Pamela{/link}, und sie erfuhr nie, was aus ihr wurde. Ihr Herz sehnt sich noch immer danach, es zu wissen.]=],
		},
		{
			title = "Taten",
			text = [=[• Sie versteckte ihre Nichte {link:pamela-redpath}Pamela{/link} in der Schlacht um {link:darrowshire}Darrowshire{/link}.
• Sie hält Wache über das Denkmal von {link:joseph-redpath}Joseph Redpath{/link}, Pamelas Vater.]=],
		},
	},
	chapters = {
		{
			title = "Josephs Ring",
			hint = "Sucht das Denkmal von Joseph Redpath zwischen den Gräbern.",
			text = [=[Joseph Redpaths Leichnam war vor langer Zeit zertrampelt worden und verloren gegangen. Sein Denkmal stand dennoch auf {link:sorrow-hill}Sorrow Hill{/link}, und darunter lag sein Ehering. Marlene trauerte, dass seine Seele zu einem Ungeheuer verzerrt worden war. Doch sie hatte von einer seltsamen Gnomin in {link:ruins-of-andorhal}Andorhal{/link} gehört, die ändern könnte, was gewesen war. Sie schickte den Ring zu {link:chromie}Chromie{/link}.]=],
		},
	},
	mentions = {
		{ text = "{link:pamela-redpath}Die kleine Pamela{/link}" },
		{ text = "Tante Marlene" },
		{ text = "Eine seltsame Historikerin" },
	},
	bonds = {
		{ id = "chromie", name = "Chromie", note = "die seltsame Historikerin, an die sie sich wandte" },
	},
})

Translate("deDE", "mulgris-deepriver", {
	title = "Mulgris Deepriver",
	subtitle = "Heiler der Tiere",
	found = "Eine Hütte auf dem Trostlosen Feld",
	hint = [=[Sucht den sterbenden Druiden in einer Hütte auf dem Trostlosen Feld.]=],
	allegiance = "Druiden des Zirkels des Cenarius",
	aliases = { "Mulgris" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Mulgris Deepriver ist ein {link:tauren}Tauren{/link}druide, der in die Pestländer kam, um zu heilen, was die Seuche ihren Tieren angetan hatte. Allein konnte er wenig gegen die {link:scourge}Geißel{/link} ausrichten, und er fand kein Heilmittel. Die Seuche nahm ihm das Augenlicht, und sie nimmt ihm den Rest. Er bittet nur darum, dass den kranken Tieren des Landes ein gnädiges Ende gewährt wird.]=],
		},
		{
			title = "Taten",
			text = [=[• Er versuchte, die Tiere der Pestländer zu heilen, bis er selbst erkrankte.
• Er schrieb, was er über die Seuche erfahren hatte, auf einen glyphenverzierten Eichenast.]=],
		},
	},
	chapters = {
		{
			title = "Auch die Tierwelt leidet",
			hint = "Gewährt den seuchenkranken Tieren ihre Erlösung.",
			text = [=[Als die kranken Wölfe und Grizzlys erlöst waren, spürte Mulgris ihre Geister zur Ruhe kommen. Dann gab er den Ast her, auf den er sein Wissen geschrieben hatte. Er sagte, die Kreaturen dieses Landes könnten nun ruhen, und er ebenso. Mit einem letzten Atemzug starb er auf dem Boden der Hütte. Der Ast ging an die Druiden des {link:cenarion-circle}Zirkels des Cenarius{/link}, nach {link:darnassus}Darnassus{/link} oder nach {link:thunder-bluff}Thunder Bluff{/link}.]=],
		},
	},
	mentions = {
		{ text = "Auch die Tierwelt leidet" },
		{ text = "Glyphenverzierter Eichenast" },
