Translate("deDE", "eva-sarkhoff", {
	title = "Eva Sarkhoff",
	subtitle = "Geist von Caer Darrow",
	found = "Caer Darrow, nahe der Burg",
	hint = [=[Sucht den Geist, der sich erinnert, neben ihrem Mann in Caer Darrow.]=],
	allegiance = "Keine",
	sections = {
