			title = "Taten",
			text = [=[• Sie und ihr Mann {link:lucien-tosselwrench}Lucien{/link} wurden vom Schlächter der Scholomance erschlagen.
• Sie sucht Gerechtigkeit gegen den Schlächter und gegen seinen Meister.]=],
		},
	},
	chapters = {
		{
			title = "Gerechtigkeit für die Sarkhoffs",
			hint = "Erfüllt die Bitte des Geistes in der Scholomance.",
			text = [=[Der Schlächter wurde vernichtet, und die Überreste von Eva und {link:lucien-tosselwrench}Lucien{/link} wurden zu Asche verbrannt. Eva spürte, wie ihr Geist zu heilen begann. Doch sie wusste, dass noch mehr zu tun war. Der Schlächter hatte einem Meister gedient, und dieser Meister lebte noch.]=],
		},
	},
	mentions = {
		{ text = "Doktor Theolen Krastinov, der Schlächter" },
